import{_ as e,o as d,c as o,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const x=JSON.parse('{"title":"Test Specification — FR 3.6.9: Approval Sequence (Creator -&gt; Manager -&gt; Client)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/test.md","filePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/test.md"}'),n={name:"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/test.md"};function l(a,t,s,r,i,g){return d(),o("div",null,[...t[0]||(t[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <strong>Test</strong> · <a href="./../../../../ba/13-task-status-and-approval-governance.html">BA Governance →</a></p><h1 id="test-specification-—-fr-3-6-9-approval-sequence-creator-gt-manager-gt-client" tabindex="-1">Test Specification — FR 3.6.9: Approval Sequence (Creator -&gt; Manager -&gt; Client) <a class="header-anchor" href="#test-specification-—-fr-3-6-9-approval-sequence-creator-gt-manager-gt-client" aria-label="Permalink to &quot;Test Specification — FR 3.6.9: Approval Sequence (Creator -&amp;gt; Manager -&amp;gt; Client)&quot;">​</a></h1><h2 id="_1-traceability-execution-summary-baseline-report-5-unit-suite" tabindex="-1">1. Traceability &amp; Execution Summary (Baseline Report 5 Unit Suite) <a class="header-anchor" href="#_1-traceability-execution-summary-baseline-report-5-unit-suite" aria-label="Permalink to &quot;1. Traceability &amp; Execution Summary (Baseline Report 5 Unit Suite)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR ID</strong></td><td style="text-align:left;"><code>FR 3.6.9</code></td></tr><tr><td style="text-align:left;"><strong>Function Name</strong></td><td style="text-align:left;">Approval Sequence (Creator -&gt; Manager -&gt; Client)</td></tr><tr><td style="text-align:left;"><strong>Functional Domain</strong></td><td style="text-align:left;">Content &amp; Task</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Target Class &amp; Method</strong></td><td style="text-align:left;"><code>TaskApprovalService.approve()</code>, <code>SectionService.approve()</code>, <code>SectionPolicy.check()</code>, <code>TaskServiceImpl.updateStatus()</code></td></tr><tr><td style="text-align:left;"><strong>Unit Test File</strong></td><td style="text-align:left;"><code>brandhub-business-service/src/test/java/com/brandhub/business/service/TaskApprovalServiceTest.java</code></td></tr><tr><td style="text-align:left;"><strong>Test Requirement</strong></td><td style="text-align:left;">Enforce multi-stage approval workflow (<code>Creator -&gt; Owner/Manager/Supervisor -&gt; Client</code>), automatic parent task settlement, anti-self-supervision, and anti-bypass guards</td></tr><tr><td style="text-align:left;"><strong>Preconditions</strong></td><td style="text-align:left;">Can connect with server; Task exists in workspace</td></tr></tbody></table><hr><h2 id="_2-unit-test-case-matrix-utcid01–utcid21-—-synchronized-with-report5-unit-test-xls" tabindex="-1">2. Unit Test Case Matrix (<code>UTCID01</code>–<code>UTCID21</code> — Synchronized with <code>Report5_Unit Test.xls</code>) <a class="header-anchor" href="#_2-unit-test-case-matrix-utcid01–utcid21-—-synchronized-with-report5-unit-test-xls" aria-label="Permalink to &quot;2. Unit Test Case Matrix (`UTCID01`–`UTCID21` — Synchronized with `Report5_Unit Test.xls`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Test Case ID</th><th style="text-align:center;">Type</th><th style="text-align:left;">Preconditions</th><th style="text-align:left;">Test Inputs</th><th style="text-align:left;">Expected Return / Exception</th><th style="text-align:left;">Log Message</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><code>UTCID01</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; Task status is ASSIGNED, no QC, no client approval</td><td style="text-align:left;"><code>action</code> = <code>submit</code></td><td style="text-align:left;">200 OK - status=MANAGER_REVIEW</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID02</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; Task status is ASSIGNED, QC assigned</td><td style="text-align:left;"><code>action</code> = <code>submit</code></td><td style="text-align:left;">200 OK - status=QC_REVIEW</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID03</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; Task status is ASSIGNED, QC approval already passed</td><td style="text-align:left;"><code>action</code> = <code>submit</code></td><td style="text-align:left;">200 OK - status=MANAGER_REVIEW (skip QC)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID04</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; Task status is ASSIGNED, QC and Manager approvals passed</td><td style="text-align:left;"><code>action</code> = <code>submit</code></td><td style="text-align:left;">200 OK - status=CLIENT_REVIEW (skip QC, Manager)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID05</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is QC assignee; Task status is QC_REVIEW</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>qc</code></td><td style="text-align:left;">200 OK - status=MANAGER_REVIEW</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID06</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is MANAGER_REVIEW, no client approval</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>manager</code></td><td style="text-align:left;">200 OK - status=COMPLETED</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID07</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is MANAGER_REVIEW, requiresClientApproval=true</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>manager</code></td><td style="text-align:left;">200 OK - status=CLIENT_REVIEW</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID08</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CLIENT of workspace; Task status is CLIENT_REVIEW</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>client</code></td><td style="text-align:left;">200 OK - status=COMPLETED</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID09</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is QC assignee; Task status is QC_REVIEW</td><td style="text-align:left;"><code>action</code> = <code>reject</code>, <code>step</code> = <code>qc</code>, <code>reason</code> = <code>needs fix</code></td><td style="text-align:left;">200 OK - status=ASSIGNED</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID10</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is MANAGER_REVIEW, QC approved</td><td style="text-align:left;"><code>action</code> = <code>reject</code>, <code>step</code> = <code>manager</code>, <code>reason</code> = <code>needs fix</code></td><td style="text-align:left;">200 OK - status=ASSIGNED, QC approval kept</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID11</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is CLIENT of workspace; Task status is CLIENT_REVIEW, Manager approved</td><td style="text-align:left;"><code>action</code> = <code>reject</code>, <code>step</code> = <code>client</code>, <code>reason</code> = <code>needs fix</code></td><td style="text-align:left;">200 OK - status=ASSIGNED, Manager approval kept</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID12</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task has 3 approval records</td><td style="text-align:left;"><code>action</code> = <code>list approvals</code></td><td style="text-align:left;">200 OK - list(step, action, actorId, comment, createdAt)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID13</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; Task status is ASSIGNED, no QC, no client approval</td><td style="text-align:left;"><code>action</code> = <code>submit</code>, <code>path</code> = <code>shortest chain</code></td><td style="text-align:left;">200 OK - submit then manager approve gives COMPLETED (2 steps)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID14</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is MANAGER_REVIEW</td><td style="text-align:left;"><code>action</code> = <code>reject</code>, <code>step</code> = <code>manager</code>, <code>reason</code> = <code>1 char</code></td><td style="text-align:left;">200 OK - status=ASSIGNED</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID15</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Task status is QC_REVIEW; User is CLIENT of workspace</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>client</code></td><td style="text-align:left;">403 WRONG_APPROVAL_STEP</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID16</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Task status is QC_REVIEW; User is MANAGER of workspace</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>manager</code></td><td style="text-align:left;">403 WRONG_APPROVAL_STEP</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID17</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Task status is QC_REVIEW; User is another creator (not QC)</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>qc</code></td><td style="text-align:left;">403 WRONG_APPROVAL_STEP</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID18</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is ASSIGNED (not submitted)</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>manager</code></td><td style="text-align:left;">409 TASK_NOT_SUBMITTED</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID19</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task status is MANAGER_REVIEW</td><td style="text-align:left;"><code>action</code> = <code>reject</code>, <code>step</code> = <code>manager</code>, <code>reason</code> = <code>null</code></td><td style="text-align:left;">400 VALIDATION_ERROR - Request validation failed</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID20</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; User is CREATOR of workspace; User is not the assignee</td><td style="text-align:left;"><code>action</code> = <code>submit</code></td><td style="text-align:left;">403 FORBIDDEN - Your role does not have permission to perform this action</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID21</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; User is MANAGER of workspace; Task does not exist</td><td style="text-align:left;"><code>action</code> = <code>approve</code>, <code>step</code> = <code>manager</code></td><td style="text-align:left;">404 TASK_NOT_FOUND - Task not found</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr></tbody></table><hr><h2 id="_3-multi-role-auto-settlement-acceptance-test-matrix-v4-0-—-ta-44-to-ta-62" tabindex="-1">3. Multi-Role &amp; Auto-Settlement Acceptance Test Matrix (v4.0 — <code>TA-44</code> to <code>TA-62</code>) <a class="header-anchor" href="#_3-multi-role-auto-settlement-acceptance-test-matrix-v4-0-—-ta-44-to-ta-62" aria-label="Permalink to &quot;3. Multi-Role &amp; Auto-Settlement Acceptance Test Matrix (v4.0 — `TA-44` to `TA-62`)&quot;">​</a></h2><p>Bộ kịch bản kiểm chứng toàn diện cho các tiêu chí nghiệm thu <code>AC-01</code> – <code>AC-16</code> trong <a href="./spec.html">spec.md (v4.0)</a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">ID</th><th style="text-align:center;">AC</th><th style="text-align:center;">Loại</th><th style="text-align:left;">Vai trò &amp; Điều kiện Đầu vào</th><th style="text-align:left;">Hành động Thực thi</th><th style="text-align:left;">Kết quả Mong đợi</th></tr></thead><tbody><tr><td style="text-align:left;"><code>TA-44</code></td><td style="text-align:center;"><code>AC-01</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;"><code>Owner</code> trong Workspace <code>AGENCY</code>; Task có <code>Section</code> đang <code>SUBMITTED</code></td><td style="text-align:left;"><code>Owner</code> bấm <code>Duyệt</code> phần, chọn kênh đăng (<code>targetPlatforms</code>) và thêm <code>Subtask</code></td><td style="text-align:left;"><code>200 OK</code>; phần chuyển <code>INTERNAL_APPROVED</code>, kênh đăng được cập nhật, không bị chặn bởi lỗi chỉ cho <code>Manager</code>.</td></tr><tr><td style="text-align:left;"><code>TA-45</code></td><td style="text-align:center;"><code>AC-01</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;"><code>Owner</code> tự nhận <code>assigneeId</code> trên Task đang <code>TODO</code></td><td style="text-align:left;"><code>Owner</code> bấm <code>Bắt đầu làm</code> (<code>POST /tasks/{id}/start</code>)</td><td style="text-align:left;"><code>200 OK</code>; Task chuyển <code>IN_PROGRESS</code> (không còn lỗi <code>403 FORBIDDEN</code>).</td></tr><tr><td style="text-align:left;"><code>TA-46</code></td><td style="text-align:center;"><code>AC-02</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Senior <code>Creator</code> được gán làm <code>task.supervisorId</code> (khác <code>assigneeId</code>), <code>Subtask</code> không có <code>supervisorOverrideId</code></td><td style="text-align:left;">Senior <code>Creator</code> bấm <code>Approve</code> / <code>Return</code> trên <code>Section</code> đang <code>SUBMITTED</code></td><td style="text-align:left;"><code>200 OK</code>; kế thừa đúng <code>task.supervisorId</code>, cho phép duyệt/trả lại nội bộ.</td></tr><tr><td style="text-align:left;"><code>TA-47</code></td><td style="text-align:center;"><code>AC-03</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Task đã gán <code>task.supervisorId = User A</code>, nhưng <code>Manager B</code> khác trong Workspace đang trực</td><td style="text-align:left;"><code>Manager B</code> bấm <code>Approve</code> trên <code>Section</code> hoặc <code>Task</code> ở bước <code>MANAGER</code></td><td style="text-align:left;"><code>200 OK</code>; <code>Manager B</code> duyệt hỗ trợ thành công, không gây kẹt khi <code>User A</code> vắng mặt.</td></tr><tr><td style="text-align:left;"><code>TA-48</code></td><td style="text-align:center;"><code>AC-04</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Creator</code> tạo mới <code>Standalone Task</code> (để trống <code>supervisorId</code> hoặc truyền chính ID của mình), sau đó bấm <code>Submit</code></td><td style="text-align:left;">Tạo Task → Lưu bài → <code>POST /submit</code></td><td style="text-align:left;"><code>task.supervisorId</code> tự động gán về <code>defaultManager</code>; <code>skipsAgencyReview == false</code>; Task bắt buộc vào <code>IN_REVIEW / MANAGER</code>, <strong>không</strong> tự nhảy lên <code>FINISHED</code>.</td></tr><tr><td style="text-align:left;"><code>TA-49</code></td><td style="text-align:center;"><code>AC-04</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Manager</code> gọi <code>PATCH /tasks/{id}/field</code> gán <code>supervisorId</code> trùng với <code>assigneeId</code> là <code>Creator</code></td><td style="text-align:left;"><code>PATCH /field</code> (<code>supervisorId = creatorId</code>)</td><td style="text-align:left;">Bị từ chối <code>400 INVALID_TASK_SUPERVISOR</code>; giữ nguyên người giám sát hợp lệ.</td></tr><tr><td style="text-align:left;"><code>TA-50</code></td><td style="text-align:center;"><code>AC-05</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Creator</code> khác trong Workspace (không tham gia Task hay Subtask)</td><td style="text-align:left;">Gọi <code>PATCH /partners</code> hoặc <code>POST /posts/{postId}/publish</code> hoặc đọc <code>Section INTERNAL</code></td><td style="text-align:left;">Bị từ chối <code>403 FORBIDDEN</code>; phần <code>INTERNAL</code> không xuất hiện trong <code>GET /sections</code>.</td></tr><tr><td style="text-align:left;"><code>TA-51</code></td><td style="text-align:center;"><code>AC-06</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Client</code> truy cập Task có cả phần <code>INTERNAL</code> (<code>POST.BRIEF</code>) và phần <code>OUTPUT</code> (<code>POST.CAPTION</code>)</td><td style="text-align:left;"><code>GET /sections</code> &amp; xem lịch sử phiên bản (<code>GET /versions</code>)</td><td style="text-align:left;">Chỉ nhận phần <code>OUTPUT</code> đã <code>INTERNAL_APPROVED</code>/<code>CLIENT_APPROVED</code>; phần <code>INTERNAL</code> ẩn 100%; <code>GET /versions</code> trả <code>403 FORBIDDEN</code>.</td></tr><tr><td style="text-align:left;"><code>TA-52</code></td><td style="text-align:center;"><code>AC-07</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Task <code>POST</code> đang ở <code>TODO</code> (đã đủ Brief &amp; Chiến dịch hợp lệ); <code>Creator</code> giữ vai trò <code>POST_CAPTION</code> (không phải <code>task.assigneeId</code>) mở Editor lưu caption</td><td style="text-align:left;"><code>POST /tasks/{id}/post</code></td><td style="text-align:left;">Hệ thống tự chuyển Task cha <code>TODO → IN_PROGRESS</code> và lưu nháp thành công, không báo lỗi khóa nội dung.</td></tr><tr><td style="text-align:left;"><code>TA-53</code></td><td style="text-align:center;"><code>AC-08</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Task có 5 <code>Section</code>, <code>requiresClientApproval = false</code>; <code>Manager</code> bấm duyệt phần cuối cùng (<code>5/5</code>)</td><td style="text-align:left;"><code>POST /sections/{lastKey}/approve</code></td><td style="text-align:left;">Toàn bộ 5 <code>Subtask</code> chuyển <code>FINISHED</code>, <strong>Task cha tự động chuyển ngay từ <code>IN_PROGRESS</code> sang <code>FINISHED</code></strong>, <code>Post</code> chuyển <code>SCHEDULED</code> / <code>APPROVED</code>.</td></tr><tr><td style="text-align:left;"><code>TA-54</code></td><td style="text-align:center;"><code>AC-08</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Task có 4 <code>Section</code>, <code>requiresClientApproval = true</code>; <code>Manager</code> duyệt đủ 4/4 phần nội bộ</td><td style="text-align:left;"><code>POST /sections/{lastKey}/approve</code> (bởi <code>Manager</code>), sau đó <code>Client</code> duyệt phần <code>OUTPUT</code> cuối cùng</td><td style="text-align:left;">Sau bước <code>Manager</code>: Task cha tự chuyển <code>IN_PROGRESS → IN_REVIEW (CLIENT)</code>. Sau bước <code>Client</code> cuối cùng: <strong>Task cha tự chuyển sang <code>FINISHED</code></strong>.</td></tr><tr><td style="text-align:left;"><code>TA-55</code></td><td style="text-align:center;"><code>AC-08</code></td><td style="text-align:center;">Edge</td><td style="text-align:left;"><code>requiresClientApproval = true</code>; <code>Client</code> đã duyệt xong 3 phần <code>OUTPUT</code> trước khi <code>Manager</code> duyệt xong phần <code>POST.BRIEF</code> (<code>INTERNAL</code>)</td><td style="text-align:left;"><code>Manager</code> bấm <code>Approve</code> phần <code>POST.BRIEF</code> cuối cùng</td><td style="text-align:left;">Ngay khi <code>POST.BRIEF</code> đạt <code>INTERNAL_APPROVED</code>, 4/4 phần đều <code>finalState = true</code> → <strong>Task cha tự chuyển ngay sang <code>FINISHED</code></strong>.</td></tr><tr><td style="text-align:left;"><code>TA-56</code></td><td style="text-align:center;"><code>AC-09</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Task vừa sang <code>FINISHED</code> và có lịch hẹn đăng ngày mai (chưa đăng); <code>Owner</code> / <code>Manager</code> phát hiện lỗi và bấm <code>Reopen</code> phần <code>POST.CAPTION</code></td><td style="text-align:left;"><code>POST /sections/POST.CAPTION/reopen</code></td><td style="text-align:left;">Phần <code>POST.CAPTION</code> về <code>RETURNED</code> (các phần khác giữ nguyên đã duyệt), <strong>Task cha tự quay về <code>IN_PROGRESS</code></strong>, lịch hẹn đăng trên <code>PostDocument</code> tự động bị hủy (<code>DRAFT</code>).</td></tr><tr><td style="text-align:left;"><code>TA-57</code></td><td style="text-align:center;"><code>AC-10</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Creator</code> (hoặc <code>Manager</code>) kéo thẻ Kanban hoặc dùng Bulk Action / gọi <code>PATCH /tasks/{id}/status</code> với <code>status = &quot;FINISHED&quot;</code> hoặc <code>&quot;IN_REVIEW&quot;</code></td><td style="text-align:left;">Kéo thẻ sang cột <code>Hoàn thành</code> / gọi <code>PATCH /status</code></td><td style="text-align:left;">Backend từ chối <code>409 TASK_WORKFLOW_REQUIRED</code>; Frontend chặn thả thẻ và hiển thị thông báo hướng dẫn đi qua quy trình duyệt.</td></tr><tr><td style="text-align:left;"><code>TA-58</code></td><td style="text-align:center;"><code>AC-10</code></td><td style="text-align:center;">Security</td><td style="text-align:left;"><code>Creator</code> gọi <code>PATCH /tasks/{id}/status</code> với <code>status = &quot;CANCELLED&quot;</code></td><td style="text-align:left;"><code>PATCH /status</code> (<code>CANCELLED</code>)</td><td style="text-align:left;">Bị từ chối <code>403 FORBIDDEN</code>; chỉ <code>Owner</code> và <code>Manager</code> mới được hủy Task.</td></tr><tr><td style="text-align:left;"><code>TA-59</code></td><td style="text-align:center;"><code>AC-11</code></td><td style="text-align:center;">Security</td><td style="text-align:left;">Workspace ở chế độ <code>AGENCY</code>, Task có <code>requiresClientApproval = false</code> (<code>TASK-B2A7</code>)</td><td style="text-align:left;">Mở <code>TaskDetailPanel</code> với quyền <code>Manager</code>/<code>Owner</code> hoặc gọi <code>POST /self-approve</code></td><td style="text-align:left;">Nút <code>Hoàn tất &amp; Tự duyệt</code> <strong>không xuất hiện</strong> trên giao diện; gọi trực tiếp API nhận <code>403 TASK_SELF_APPROVE_NOT_ALLOWED</code>. Trong chế độ <code>PERSONAL</code> vẫn hoạt động bình thường.</td></tr><tr><td style="text-align:left;"><code>TA-60</code></td><td style="text-align:center;"><code>AC-12,14</code></td><td style="text-align:center;">UX</td><td style="text-align:left;">Mở <code>TaskDetailPanel</code> trên Task <code>FINISHED</code> và trên Task <code>IN_PROGRESS</code> (<code>3/5</code> phần đã duyệt); duyệt nốt phần trong panel</td><td style="text-align:left;">Quan sát <code>TaskStatusControl</code> và bảng <code>TaskTable</code> phía sau</td><td style="text-align:left;">Khi <code>FINISHED</code>: hiện huy hiệu <code>• Hoàn thành</code> tĩnh (không có mũi tên <code>⌄</code>, không mở menu trống). Khi duyệt xong phần cuối trong panel: dòng bên ngoài bảng <code>TaskTable</code> tự nhảy sang <code>Hoàn thành</code> ngay tức thì.</td></tr><tr><td style="text-align:left;"><code>TA-61</code></td><td style="text-align:center;"><code>AC-13</code></td><td style="text-align:center;">Normal</td><td style="text-align:left;">Workspace có các Task <code>SHORT_VIDEO</code>, <code>KOL_BOOKING</code>, <code>EVENT_PLAN</code> đang chờ duyệt</td><td style="text-align:left;">Mở trang <code>/workspaces/:id/task-approvals</code></td><td style="text-align:left;">Hiển thị đầy đủ cả 8 loại <code>TaskType</code> và lọc chính xác theo loại công việc (không chỉ riêng <code>POST</code>).</td></tr><tr><td style="text-align:left;"><code>TA-62</code></td><td style="text-align:center;"><code>AC-15,16</code></td><td style="text-align:center;">i18n &amp; Theme</td><td style="text-align:left;">Chuyển đổi ngôn ngữ <code>VI ↔ EN</code> và giao diện <code>Light ↔ Dark</code> ở khung nhìn <code>375px</code>, <code>768px</code>, <code>1440px</code></td><td style="text-align:left;">Kiểm tra <code>TaskStatusControl</code>, <code>TaskBoardView</code>, <code>TaskBulkActionBar</code>, <code>/task-approvals</code></td><td style="text-align:left;">100% nhãn dịch khớp ngữ cảnh không lộ raw key; màu sắc tương phản rõ ràng trên cả nền Sáng và Tối, không tràn khung nhìn.</td></tr></tbody></table>',11)])])}const h=e(n,[["render",l]]);export{x as __pageData,h as default};
